public static String getRootCauseMessage(Throwable t) {
    if (t == null) return "No error";
    Throwable root = t;
    while (root.getCause() != null) {
        root = root.getCause();
    }
    return root.getMessage() != null ? root.getMessage() : root.getClass().getSimpleName();
}
